  &reftitle.description;

   public static arrayUnitEnum::cases



यो method ले कुनै enumeration का सबै cases को packed array declaration को क्रम अनुसार return गर्छ।

  &reftitle.examples;

   आधारभूत प्रयोग

तलको उदाहरणले enum case हरू कसरी return हुन्छन् भनेर देखाउँछ।


<?php
enum Suit
{
    case Hearts;
    case Diamonds;
    case Clubs;
    case Spades;
}

var_dump(Suit::cases());


   &example.outputs;


array(4) {
  [0]=>
  enum(Suit::Hearts)
  [1]=>
  enum(Suit::Diamonds)
  [2]=>
  enum(Suit::Clubs)
  [3]=>
  enum(Suit::Spades)
}
